  if(id)where.push('x.id::text='+bind(id));
  if(projects&&customer)where.push('x.customer_id::text='+bind(customer));
  const from=' from '+(projects?'projects':'customers')+' x where '+where.join(' and ');
  const total=(await c.query('select count(*)::int total'+from,values)).rows[0]?.total??0;
  const items=(await c.query('select x.id,x.name'+(projects?',x.customer_id,x.status':'')+from+' order by x.name,x.id limit '+bind(limit)+' offset '+bind(offset),values)).rows;
  return {items,total:Number(total)};
 }

async c=>{
  const row=(await c.query('select not app_is_solo_owner() as time_approval_required')).rows[0];
  if(body.required!==row.time_approval_required)throw new ApiError(409,'independent_review_required','Die Freigabe folgt der aktiven Teamzuordnung und kann hier nicht geändert werden.');
  return row;
 }

async c=>{
   const items=[];
   // Stable lock order prevents two overlapping selections from deadlocking.
   for(const id of [...ids].sort())items.push(await reviewTimeEntry(c,s,id,{action}));
   return items;
  }

async c=>{const write=async()=>{
      const project=cleanText(body.projectName,200),projectId=cleanText(body.projectId,80),customerId=cleanText(body.customerId,80);
      const found=body.projectId===null?{rows:[],rowCount:0}:projectId?await c.query("select id,name,customer_id,status from projects where organization_id=$1 and id=$2 and archived_at is null for share",[s.organizationId,projectId]):await c.query("select id,name,customer_id,status from projects where organization_id=$1 and name=$2 and archived_at is null for share",[s.organizationId,project]);
      if(found.rowCount&&found.rowCount>1)throw new ApiError(409,"ambiguous_project","Bitte einen eindeutigen Auftrag auswählen.");
      if(projectId&&found.rowCount!==1)throw new ApiError(400,"project_invalid","Bitte einen gültigen Auftrag auswählen.");
      if(found.rows[0]&&!projectAllowsTime(found.rows[0].status))throw new ApiError(409,"project_not_active","Für diesen Auftrag können momentan keine Zeiten erfasst werden.");
      const customers=customerId?await c.query("select id from customers where organization_id=$1 and id=$2 and archived_at is null",[s.organizationId,customerId]):null;
      if(customerId&&customers?.rowCount!==1)throw new ApiError(400,"customer_invalid","Bitte einen gültigen Kunden auswählen.");
      if(customerId&&found.rows[0]?.customer_id&&String(found.rows[0].customer_id)!==customerId)throw new ApiError(400,"project_customer_mismatch","Der Auftrag gehört nicht zum gewählten Kunden.");
      const resolvedCustomer=customers?.rows[0]?.id??found.rows[0]?.customer_id??null;
      if(body.billable===true&&!resolvedCustomer)throw new ApiError(400,"billable_customer_required","Verrechenbare Zeiten benötigen einen Kunden.");
      await assertTimeAssignment(c,s,resolvedCustomer,found.rows[0]?.id??null,workDate.toISOString().slice(0,10));
      if(reportMonth&&(!resolvedCustomer||body.billable===false))throw new ApiError(400,"report_customer_required","Ein Monatsrapport benötigt einen Kunden und verrechenbare Stunden.");
      const billable=Boolean(resolvedCustomer)&&body.billable!==false;
      const employee=await c.query("select id from employees where organization_id=$1 and archived_at is null and active and user_id=$2",[s.organizationId,s.userId]);
      if(["member","project_manager","manager"].includes(s.role)&&!employee.rowCount)throw new ApiError(403,"employee_unlinked","Der Benutzerzugang ist keinem aktiven Mitarbeiter zugeordnet.");
      if(classification?.payrollRelevant&&!employee.rowCount)throw new ApiError(400,'employee_required','Lohnrelevante Zeit benötigt ein Mitarbeiterdossier.');
      const approvalRequired=(await c.query("select not app_is_solo_owner() as time_approval_required from organizations where id=$1",[s.organizationId])).rows[0]?.time_approval_required!==false;
      const result=await c.query(`insert into time_entries(organization_id,external_id,project_id,customer_id,employee_id,project_label,person_name,worker_type,work_date,hours,description,billable,approved,created_by_user_id,sales_rate,report_month,time_category,is_work_time,payroll_relevant)
        values($1,$2,$3,$9,$10,$11,$4,'employee',$5,$6,$7,$12,$14,$8,$13,$15,$16,$17,$18)
        returning id,time_category,is_work_time,payroll_relevant,created_by_user_id,report_month,project_id,project_label as project_name,description,work_date as started_at,round(hours*60) as duration_minutes,customer_id,employee_id,billable,approved,invoiced_invoice_id,sales_rate,created_at`,
        [s.organizationId,randomUUID(),found.rows[0]?.id??null,s.name,workDate.toISOString().slice(0,10),duration/60,cleanText(body.description,2000)||project,s.userId,customers?.rows[0]?.id??found.rows[0]?.customer_id??null,employee.rows[0]?.id??null,found.rows[0]?.name??project,billable,["member"].includes(s.role)?0:salesRate,reportMonth?false:billable&&!approvalRequired,reportMonth?reportMonth+"-01":null,classification?.category??null,classification?.isWorkTime??null,classification?.payrollRelevant??null]);
      const context=(await c.query("select c.name customer_name,coalesce(nullif(concat_ws(' ',e.first_name,e.last_name),''),t.person_name) employee_name from time_entries t left join customers c on c.id=t.customer_id and c.organization_id=t.organization_id left join employees e on e.id=t.employee_id and e.organization_id=t.organization_id where t.id=$1 and t.organization_id=$2",[result.rows[0].id,s.organizationId])).rows[0];
      return {...result.rows[0],...context};
    };return requestKey?idempotentBusiness(c,{organizationId:s.organizationId,userId:s.userId,operation:"time.manual.create",key:requestKey,body},write):write();}

async c=>{
      const result=await c.query("select *, accumulated_seconds + case when state='running' and active_since is not null then greatest(0,extract(epoch from now()-active_since)::integer) else 0 end as seconds from active_time_trackers where organization_id=$1 and user_id=$2",[s.organizationId,s.userId]);
      return {tracker:result.rows[0]??null};
    }

async c=>{
      await c.query("select pg_advisory_xact_lock(hashtextextended($1,0))",[s.organizationId+":"+s.userId]);
      const result=await c.query("select *, accumulated_seconds + case when state='running' and active_since is not null then greatest(0,extract(epoch from now()-active_since)::integer) else 0 end as seconds from active_time_trackers where organization_id=$1 and user_id=$2 for update",[s.organizationId,s.userId]);
      const current=result.rows[0];const seconds=Number(current?.seconds??0);
      const label=cleanText(body.project,200)||current?.project_label||"Arbeitszeit";
      if(body.action==="finish"){
        if(!current)return {tracker:null};
        if(seconds<=0)throw new ApiError(400,"empty_tracker","Es läuft noch keine Zeitmessung.");
        await assertTimeAssignment(c,s,current.customer_id,current.project_id,businessDate());
        const entry=await c.query(`insert into time_entries(organization_id,external_id,person_name,worker_type,work_date,hours,description,billable,approved,created_by_user_id,project_id,project_label,employee_id,customer_id)
          values($1,$2,$3,'employee',(now() at time zone 'Europe/Zurich')::date,$4,$5,$6,$6 and app_is_solo_owner(),$7,$8,$9,(select id from employees where organization_id=$1 and user_id=$7 and archived_at is null limit 1),coalesce($10::uuid,(select customer_id from projects where id=$8 and organization_id=$1))) returning id,description,work_date,hours,created_at`,
          [s.organizationId,randomUUID(),s.name,seconds/3600,current.project_label+" · "+current.activity_label,current.billable,s.userId,current.project_id,current.project_label,current.customer_id]);
        await c.query("delete from active_time_trackers where organization_id=$1 and user_id=$2",[s.organizationId,s.userId]);
        return {tracker:null,item:entry.rows[0]};
      }
      if(body.action==="pause"){
        if(!current)return {tracker:null};
        const paused=await c.query("update active_time_trackers set state='paused',active_since=null,accumulated_seconds=$3,updated_at=now() where organization_id=$1 and user_id=$2 returning *,accumulated_seconds as seconds",[s.organizationId,s.userId,seconds]);
        return {tracker:paused.rows[0]};
      }
      const projectId=body.projectId===undefined?current?.project_id:cleanText(body.projectId,80);
      const customerId=body.customerId===undefined?current?.customer_id:cleanText(body.customerId,80);
      if(customerId){const customer=await c.query("select id from customers where organization_id=$1 and id=$2 and archived_at is null",[s.organizationId,customerId]);if(customer.rowCount!==1)throw new ApiError(400,"customer_invalid","Bitte einen gültigen Kunden auswählen.");}
      const projects=body.projectId===null?{rows:[],rowCount:0}:projectId?await c.query("select id,name,customer_id,status from projects where organization_id=$1 and id=$2 and archived_at is null for share",[s.organizationId,projectId]):await c.query("select id,name,customer_id,status from projects where organization_id=$1 and name=$2 and archived_at is null for share",[s.organizationId,label]);
      if(projects.rowCount&&projects.rowCount>1)throw new ApiError(409,"ambiguous_project","Bitte einen eindeutigen Auftrag auswählen.");
      if(projectId&&projects.rowCount!==1)throw new ApiError(400,"project_invalid","Bitte einen gültigen Auftrag auswählen.");
      if(body.action!=="pause"&&projects.rows[0]&&!projectAllowsTime(projects.rows[0].status))throw new ApiError(409,"project_not_active","Für diesen Auftrag können momentan keine Zeiten erfasst werden.");
      if(customerId&&projects.rows[0]?.customer_id&&String(projects.rows[0].customer_id)!==customerId)throw new ApiError(400,"project_customer_mismatch","Der Auftrag gehört nicht zum gewählten Kunden.");
      const resolvedCustomer=customerId||projects.rows[0]?.customer_id||null;
      if(body.action!=="pause")await assertTimeAssignment(c,s,resolvedCustomer,projects.rows[0]?.id??null,businessDate());
      if(current&&seconds>0&&(String(current.customer_id??"")!==String(resolvedCustomer??"")||String(current.project_id??"")!==String(projects.rows[0]?.id??"")||current.project_label!==label))throw new ApiError(409,"tracker_context_locked","Bitte die erfasste Zeit zuerst stoppen, bevor du den Kunden oder Auftrag wechselst.");
      const running=body.action==="start"||(body.action==="project"&&current?.state==="running");
      const saved=await c.query(`insert into active_time_trackers(organization_id,user_id,state,active_since,accumulated_seconds,project_label,project_id,customer_id,billable)
        values($1,$2,$3,case when $3='running' then now() else null end,$4,$5,$6,$7,$8)
        on conflict(organization_id,user_id) do update set state=excluded.state,active_since=excluded.active_since,
        accumulated_seconds=excluded.accumulated_seconds,project_label=excluded.project_label,project_id=excluded.project_id,customer_id=excluded.customer_id,billable=excluded.billable,updated_at=now() returning *,accumulated_seconds as seconds`,
        [s.organizationId,s.userId,running?"running":"paused",seconds,label,projects.rows[0]?.id??null,resolvedCustomer,Boolean(resolvedCustomer)]);
      return {tracker:{...saved.rows[0],customer_id:resolvedCustomer}};
    }

