/** Phase 1 navigation V2. Destinations retain the existing server-matched access check. */
// Each label names one functional area; ampersand pairs are excluded in every locale.
export const mainNavigation = [
 {href:'/dashboard',label:'Übersicht',icon:'house',section:'dashboard'},
 {href:'/kunden',label:'Kunden',icon:'navigation-users',section:'kunden'},
 {href:'/projekte',label:'Aufträge',icon:'briefcase-business',section:'projekte'},
 {href:'/zeit',label:'Zeit',icon:'clock3',section:'zeit'},
] as const;

export const moreNavigation = [
 {title:'Geschäft',items:[
  {href:'/angebote',label:'Angebote',icon:'file'},
  {href:'/rechnungen',label:'Rechnungen',icon:'receipt'},
  {href:'/zahlungen',label:'Zahlungen',icon:'wallet'},
  {href:'/spesen',label:'Spesen',icon:'card'},
  {href:'/finanzen',label:'Finanzübersicht',icon:'chart'},
  {href:'/produkte',label:'Produkte',icon:'box'},
  {href:'/lieferanten',label:'Lieferanten',icon:'building'},
  {href:'/vertraege',label:'Verträge',icon:'file'},
 ]},
 {title:'Auswertung',items:[{href:'/berichte',label:'Berichte',icon:'chart'}]},
 {title:'Verwaltung',items:[
  {href:'/einstellungen/firma',label:'Unternehmen',icon:'building'},
  {href:'/einstellungen/team',label:'Benutzerkonten',icon:'users'},
  {href:'/mitarbeiter',label:'Mitarbeiter',icon:'users'},
  {href:'/abwesenheiten',label:'Abwesenheiten',icon:'calendar'},
  {href:'/einstellungen',label:'Einstellungen',icon:'settings'},
 ]},
 {title:'Hilfe',items:[
  {href:'/support',label:'Support',icon:'support'},
  {href:'/hilfe',label:'Hilfe',icon:'help'},
 ]},
] as const;

/** Nested routes keep their owning primary destination; every other route belongs to More. */
export function primaryNavigationSection(pathname:string){
 return mainNavigation.find(item=>pathname===item.href||pathname.startsWith(item.href+'/'))?.section??'more';
}

/** Conservative public baseline. Device settings use authenticated server capabilities. */
export const notificationChannels={email:true,push:false} as const;
export const notificationPreferenceKinds=['Rechnungen','Angebote','Support','Zeiterfassung','Spesen','Sicherheit','Produktupdates'] as const;

export type TenantRole="owner"|"admin"|"finance"|"hr"|"project_manager"|"manager"|"member"|"reader";
export type ModuleProfile='standard'|'time_only';
const timeOnlyPermissions=new Set(['time:read','time:write','documents:read','support:read','support:write','feedback:write']);
export function profileAllowsPath(profile:ModuleProfile|undefined,path:string){
 if(profile===undefined||profile==='standard')return true;
 if(profile!=='time_only')return false;
 return path==='/zeit'||path.startsWith('/zeit/')||path==='/support'||path.startsWith('/support/')||path==='/hilfe'||['/einstellungen','/einstellungen/konto','/einstellungen/sicherheit','/einstellungen/benachrichtigungen','/einstellungen/darstellung','/einstellungen/sprache','/einstellungen/datenschutz','/benachrichtigungen'].includes(path);
}
/** Personal settings never grant company settings or business-data access. */
export function tenantCanOpenPath(role:string,path:string,profile:ModuleProfile='standard'){
 if(!Object.hasOwn(tenantGrants,role))return false;
 if(!profileAllowsPath(profile,path))return false;
 if(profile==='time_only'&&role!=='member')return false;
 if(profile==='time_only'&&(path==='/einstellungen'||path.startsWith('/einstellungen/')||path==='/benachrichtigungen'))return true;
 const permission=routePermission(path);
 return !permission||tenantCan(role,permission,profile);
}
export type LocalUserRole="Inhaber"|"Admin"|"Finanzen"|"Personal"|"Projektleitung"|"Mitarbeiter"|"Lesen";

export type TenantPermission=
 |"finance-overview:read"
 |"organization:read"|"organization:write"|"users:read"|"users:manage"|"billing:read"|"billing:write"|"audit:read"
 |"customers:read"|"customers:write"|"customers:delete"
 |"sales:read"|"sales:write"|"invoices:read"|"invoices:write"|"payments:read"|"payments:write"
 |"projects:read"|"projects:write"|"time:read"|"time:write"|"expenses:read"|"expenses:write"|"tasks:read"|"tasks:write"
 |"purchasing:read"|"purchasing:write"|"accounting:read"|"accounting:write"|"bank:read"|"bank:write"|"vat:read"|"vat:write"|"reports:read"
 |"employees:read"|"employees:write"|"absence:read"|"absence:write"|"payroll:read"|"payroll:write"
 |"masterdata:read"|"masterdata:write"|"documents:read"|"documents:write"|"contracts:read"|"contracts:write"
 |"support:read"|"support:write"|"feedback:write";

const allPermissions:TenantPermission[]=[
 "organization:read","organization:write","users:read","users:manage","billing:read","billing:write","audit:read",
 "customers:read","customers:write","customers:delete","sales:read","sales:write","invoices:read","invoices:write","payments:read","payments:write",
 "projects:read","projects:write","time:read","time:write","expenses:read","expenses:write","tasks:read","tasks:write",
 "purchasing:read","purchasing:write","accounting:read","accounting:write","bank:read","bank:write","vat:read","vat:write","reports:read",
 "employees:read","employees:write","absence:read","absence:write","payroll:read","payroll:write",
 "masterdata:read","masterdata:write","documents:read","documents:write","contracts:read","contracts:write"
];

const baseRead:TenantPermission[]=["organization:read","customers:read","sales:read","invoices:read","projects:read","tasks:read","masterdata:read","documents:read","contracts:read","reports:read"];

export const tenantGrants:Record<TenantRole,ReadonlySet<TenantPermission>>={
 owner:new Set(allPermissions),
 admin:new Set(allPermissions.filter(p=>p!=="billing:write")),
 finance:new Set([
  "organization:read","users:read","billing:read","customers:read","customers:write","sales:read","invoices:read","invoices:write","payments:read","payments:write",
  "time:read","expenses:read","expenses:write","purchasing:read","purchasing:write","accounting:read","accounting:write","bank:read","bank:write","vat:read","vat:write","reports:read","documents:read","documents:write","contracts:read"
 ]),
 hr:new Set(["organization:read","users:read","employees:read","employees:write","absence:read","absence:write","payroll:read","payroll:write","documents:read","documents:write","reports:read"]),
 project_manager:new Set(["organization:read","customers:read","customers:write","sales:read","sales:write","projects:read","projects:write","time:read","time:write","expenses:read","expenses:write","tasks:read","tasks:write","masterdata:read","documents:read","documents:write","contracts:read","reports:read"]),
 manager:new Set(["organization:read","customers:read","customers:write","sales:read","sales:write","projects:read","projects:write","time:read","time:write","expenses:read","expenses:write","tasks:read","tasks:write","masterdata:read","documents:read","documents:write","contracts:read","reports:read"]),
 member:new Set(["organization:read","customers:read","projects:read","time:read","time:write","expenses:read","expenses:write","tasks:read","tasks:write","masterdata:read","documents:read"]),
 reader:new Set(baseRead)
};

export function normalizeTenantRole(role:string):TenantRole{
 if(role==="manager")return "project_manager";
 return (["owner","admin","finance","hr","project_manager","member","reader"] as string[]).includes(role)?role as TenantRole:"reader";
}
const universalTenantPermissions=new Set<TenantPermission>(["support:read","support:write","feedback:write"]);
export function tenantCan(role:string,permission:TenantPermission,profile:ModuleProfile='standard'){
 if(profile!=='standard'&&(profile!=='time_only'||role!=='member'||!timeOnlyPermissions.has(permission)))return false;
 if(!Object.hasOwn(tenantGrants,role))return false;
 const grants=tenantGrants[normalizeTenantRole(role)];
 // Derived read capability, not an additional grant to documents-only roles.
 if(permission==='finance-overview:read')return grants.has('documents:read')&&(['accounting:read','invoices:read','sales:read'] as TenantPermission[]).some(item=>grants.has(item));
 return universalTenantPermissions.has(permission)||grants.has(permission);
}
export function tenantPermissions(role:string,profile:ModuleProfile='standard'){return Object.hasOwn(tenantGrants,role)?Array.from(new Set([...tenantGrants[normalizeTenantRole(role)],...universalTenantPermissions,...(tenantCan(role,'finance-overview:read',profile)?['finance-overview:read' as const]:[])])).filter(permission=>tenantCan(role,permission,profile)):[]}

export function localRoleToTenant(role:LocalUserRole|string):TenantRole{
 const map:Record<string,TenantRole>={Inhaber:"owner",Admin:"admin",Finanzen:"finance",Personal:"hr",Projektleitung:"project_manager",Mitarbeiter:"member",Lesen:"reader"};
 return map[role]||"reader";
}

export const modulePermissionMap:Record<string,{read:TenantPermission;write:TenantPermission}>={
 finanzen:{read:"accounting:read",write:"accounting:write"},
 kunden:{read:"customers:read",write:"customers:write"},
 offerten:{read:"sales:read",write:"sales:write"},auftraege:{read:"sales:read",write:"sales:write"},
 rechnungen:{read:"invoices:read",write:"invoices:write"},zahlungen:{read:"payments:read",write:"payments:write"},
 projekte:{read:"projects:read",write:"projects:write"},zeiterfassung:{read:"time:read",write:"time:write"},spesen:{read:"expenses:read",write:"expenses:write"},aufgaben:{read:"tasks:read",write:"tasks:write"},
 lieferanten:{read:"purchasing:read",write:"purchasing:write"},eingangsrechnungen:{read:"purchasing:read",write:"purchasing:write"},
 buchhaltung:{read:"accounting:read",write:"accounting:write"},bank:{read:"bank:read",write:"bank:write"},mwst:{read:"vat:read",write:"vat:write"},berichte:{read:"reports:read",write:"reports:read"},
 personal:{read:"employees:read",write:"employees:write"},abwesenheiten:{read:"absence:read",write:"absence:write"},lohn:{read:"payroll:read",write:"payroll:write"},
 produkte:{read:"masterdata:read",write:"masterdata:write"},dokumente:{read:"documents:read",write:"documents:write"},vertraege:{read:"contracts:read",write:"contracts:write"},
 einstellungen:{read:"organization:read",write:"organization:write"},support:{read:"support:read",write:"support:write"}
};

export function permissionForModule(moduleKey:string,action:"read"|"write"){return modulePermissionMap[moduleKey]?.[action]}
export function routePermission(pathname:string):TenantPermission|undefined{
 if(pathname==='/hilfe')return 'support:read';
 if(pathname==='/benachrichtigungen')return 'organization:read';
 if(pathname==="/finanzen"||pathname==="/belege")return "finance-overview:read";
 if(pathname==="/einstellungen/team")return "users:read";
 if(pathname==="/einstellungen/abonnement")return "billing:read";
 if(pathname.startsWith("/einstellungen"))return "organization:read";
 const segment=pathname.split("/").filter(Boolean)[0]||"dashboard";
 if(segment==="dashboard")return "organization:read";
 const aliases:Record<string,string>={angebote:"offerten",zeit:"zeiterfassung",mitarbeiter:"personal",belege:"dokumente"};
 return permissionForModule(aliases[segment]??segment,"read");
}
/** Creating an unassigned customer/order is an administrative boundary.
 * Existing role permissions still control every other creation route. */
export function tenantCanCreateAt(role:string,path:string,profile:ModuleProfile='standard'){
 const area=path.split('/')[1],key=({angebote:'offerten',zeit:'zeiterfassung',mitarbeiter:'personal'} as Record<string,string>)[area]??area;
 const permission=permissionForModule(key,'write');
 if(!permission||!tenantCan(role,permission,profile)||!profileAllowsPath(profile,path))return false;
 if(area==='projekte')return ['owner','admin'].includes(role);
 if(area==='kunden')return ['owner','admin','finance'].includes(role);
 return true;
}
export function ownRecordOnly(role:string,moduleKey:string){
 return normalizeTenantRole(role)==="member"&&["zeiterfassung","spesen","aufgaben"].includes(moduleKey);
}

export type OperatorRole="platform_owner"|"platform_admin"|"platform_support"|"platform_billing"|"platform_auditor";
export type OperatorPermission="platform:read"|"organizations:read"|"organizations:manage"|"subscriptions:read"|"subscriptions:manage"|"operators:read"|"operators:manage"|"platform_audit:read"|"support:manage"|"feedback:manage"|"feature_flags:manage"|"announcements:manage"|"security:manage"|"restrictions:manage"|"integrations:test";
export const operatorGrants:Record<OperatorRole,ReadonlySet<OperatorPermission>>={
 platform_owner:new Set(["platform:read","organizations:read","organizations:manage","subscriptions:read","subscriptions:manage","operators:read","operators:manage","platform_audit:read","support:manage","feedback:manage","feature_flags:manage","announcements:manage","security:manage","restrictions:manage","integrations:test"]),
 platform_admin:new Set(["platform:read","organizations:read","organizations:manage","subscriptions:read","subscriptions:manage","operators:read","platform_audit:read","support:manage","feedback:manage","feature_flags:manage","announcements:manage","restrictions:manage","integrations:test"]),
 platform_support:new Set(["platform:read","organizations:read","support:manage","feedback:manage"]),
 platform_billing:new Set(["platform:read","organizations:read","subscriptions:read","subscriptions:manage"]),
 platform_auditor:new Set(["platform:read","organizations:read","operators:read","platform_audit:read"])
};
export function operatorCan(role:OperatorRole|string,permission:OperatorPermission){return Object.hasOwn(operatorGrants,role)&&operatorGrants[role as OperatorRole].has(permission)}
export function operatorPermissions(role:OperatorRole|string){return Object.hasOwn(operatorGrants,role)?Array.from(operatorGrants[role as OperatorRole]):[]}

import {operatorCan,type OperatorRole,type OperatorPermission} from './permissions';

/** Page access follows the same grants as the corresponding APIs. */
export const operatorPages:Record<string,OperatorPermission>={
 '':'platform:read',tickets:'support:manage',kunden:'organizations:read',
 zahlungen:'subscriptions:read',finanzen:'subscriptions:read',abonnemente:'subscriptions:read',
 sperrungen:'restrictions:manage',monitoring:'platform:read',ankuendigungen:'announcements:manage',
 sicherheit:'operators:read',audit:'platform_audit:read',
};
export function validOperatorSection(section:string){
 const parts=section.split('/');
 return Object.hasOwn(operatorPages,parts[0])&&(parts.length===1||parts.length===2&&['tickets','kunden'].includes(parts[0])&&Boolean(parts[1]));
}
export function canOpenOperatorSection(role:OperatorRole|'readonly',section:string){
 const permission=operatorPages[section.split('/')[0]];
 return Boolean(permission&&operatorCan(role,permission));
}

